// A negative-space entry is not automatically debt. Every entry above is
// reviewed here against the tale's role, staged nodes, ending prose and
// divergence notes. `justified` means the beat remains honestly available in
// the source timeline while the playable projection uses setup, narration,
// montage, repetition, aftermath or a deliberate point-of-view boundary.
// `gap` means the current projection changes or loses something central enough
// to warrant implementation. `uncertain` means the evidence needed to decide
// is still being aligned. Strict certification may accept `justified`; it must
// continue to reject `gap` and `uncertain`.
export const PROJECTION_DISPOSITIONS = Object.freeze({
  JUSTIFIED: 'justified',
  GAP: 'gap',
  UNCERTAIN: 'uncertain',
})

const JUSTIFIED = PROJECTION_DISPOSITIONS.JUSTIFIED
const GAP = PROJECTION_DISPOSITIONS.GAP
const UNCERTAIN = PROJECTION_DISPOSITIONS.UNCERTAIN

