export const PROJECTION_OMISSION_REVIEWS = Object.freeze(Object.fromEntries(
  Object.entries(PROJECTION_OMISSIONS).flatMap(([taleId, beatIds]) => beatIds.map((beatId) => {
    const policy = PROJECTION_REVIEW_POLICY[taleId]
    const review = policy?.overrides?.[beatId] || policy
    return [`${taleId}.${beatId}`, Object.freeze({
      taleId,
      beatId,
      reviewId: `omission:${taleId}.${beatId}`,
      contextHash: PROJECTION_OMISSION_CONTEXT_HASHES[`${taleId}.${beatId}`],
      itemEvidence: `${taleId}.${beatId}: justified non-enactment review; contextHash binds this exact source beat, its lines and note, and its declared scene, learn, span and divergence status.`,
      disposition: review?.disposition,
      basis: review?.basis,
      note: review?.note,
      ...(review?.recommendation ? { recommendation: review.recommendation } : {}),
    })]
  })),
))

// Proposed anchors receive the same treatment. Most are honest source-timeline
// locations or optional visual refinements around a deliberately compressed
// projection. A proposed anchor is not a promise that every narrated place
// needs its own travel node. Gjizar's compressed helper households and return
// towns have been reviewed as justified source-route detail. Binoshët's
// primary text is now aligned; its one remaining proposal is the off-route
// seaside prologue, not an unresolved source question.
const placeReview = (disposition, basis, note, keys, recommendation) =>
  Object.fromEntries(words(keys).map((key) => [key, Object.freeze({
    key,
    reviewId: `place:${key}`,
    contextHash: PLACE_PROJECTION_CONTEXT_HASHES[key],
    itemEvidence: `${key}: justified non-built anchor review; contextHash binds this exact place note, anchor mirror, mold, proposal, conflicts and declared playable scope.`,
    disposition,
    basis,
    note,
    ...(recommendation ? { recommendation } : {}),
  })]))

